let sleepDeadline=0,sleepAtTrackEnd=false,sleepTimer=null;
const quickDialog=document.createElement('dialog');quickDialog.id='quickDialog';quickDialog.className='quick-dialog';document.body.append(quickDialog);let quickMode='commands',quickLastFocus=null;
const quickCommands=[['search','Найти музыку','/'],['wave','Моя волна',''],['favorites','Любимое',''],['equalizer','Эквалайзер',''],['appearance','Оформление',''],['connections','Подключения',''],['now','Сейчас играет','Ctrl + L'],['queue','Открыть очередь',''],['timer','Таймер сна','']];
function quickCommandRows(query=''){return quickCommands.filter(([,name])=>name.toLowerCase().includes(query.toLowerCase())).map(([id,name,key])=>`<button data-command="${id}"><span>${name}</span><kbd>${key||'↵'}</kbd></button>`).join('')||'<p>Команда не найдена</p>'}
function timerDescription(){return sleepAtTrackEnd?'После текущего трека':sleepDeadline?'Осталось '+Math.max(0,Math.ceil((sleepDeadline-Date.now())/60000))+' мин.':'Таймер выключен'}
function openQuick(mode='commands'){quickMode=mode;quickLastFocus=document.activeElement;if(focusOpen)focusPanel.append(quickDialog);else document.body.append(quickDialog);quickDialog.innerHTML=mode==='timer'?`<div class="quick-title"><strong>Таймер сна</strong><button data-close-quick aria-label="Закрыть таймер">×</button></div><p id="sleepStatus">${timerDescription()}</p><div class="timer-options">${[15,30,45,60].map(min=>`<button data-sleep-minutes="${min}">${min}<span>минут</span></button>`).join('')}</div><button class="secondary" data-sleep-end ${!current?'disabled':''}>После этой песни</button><button class="secondary" data-sleep-minutes="0">Выключить таймер</button><p class="quick-note">Таймер остановит только музыку soulroom. Он не выключает компьютер.</p>`:`<div class="quick-title"><strong>Быстрые команды</strong><button data-close-quick aria-label="Закрыть команды">×</button></div><input id="commandSearch" placeholder="Куда перейти или что сделать?" aria-label="Поиск команды"><div class="command-list">${quickCommandRows()}</div><p class="quick-note">Ctrl + K — команды · Ctrl + L — плеер · ← / → — ±5 секунд</p>`;if(!quickDialog.open)quickDialog.showModal();$('#commandSearch')?.focus()}
function closeQuick(){quickDialog.close();if(quickLastFocus?.isConnected)quickLastFocus.focus()}
quickDialog.addEventListener('click',e=>{if(e.target===quickDialog)closeQuick()});quickDialog.addEventListener('input',e=>{if(e.target.id==='commandSearch')quickDialog.querySelector('.command-list').innerHTML=quickCommandRows(e.target.value)});
function stopForSleep(){clearTimeout(sleepTimer);sleepDeadline=0;sleepAtTrackEnd=false;audio.pause();updateSleepBadge();toast('Таймер сна остановил музыку.')}
function setSleep(minutes,endTrack=false){clearTimeout(sleepTimer);sleepDeadline=minutes>0?Date.now()+minutes*60000:0;sleepAtTrackEnd=endTrack;if(sleepDeadline)sleepTimer=setTimeout(stopForSleep,minutes*60000);updateSleepBadge();toast(endTrack?'Музыка остановится после этой песни.':minutes?'Таймер сна: '+minutes+' мин.':'Таймер сна выключен.')}
const sleepButton=document.createElement('button');sleepButton.id='sleepTimerButton';sleepButton.setAttribute('aria-label','Таймер сна');sleepButton.title='Таймер сна';sleepButton.innerHTML=playerIcon('clock');document.querySelector('.player-right').append(sleepButton);
const commandsButton=document.createElement('button');commandsButton.id='commandsButton';commandsButton.setAttribute('aria-label','Быстрые команды');commandsButton.title='Быстрые команды · Ctrl+K';commandsButton.innerHTML='<span>⌘ K</span>';document.querySelector('.header-right').prepend(commandsButton);
function updateSleepBadge(){sleepButton.classList.toggle('is-on',!!sleepDeadline||sleepAtTrackEnd);sleepButton.title=timerDescription();sleepButton.setAttribute('aria-label','Таймер сна: '+timerDescription());if($('#sleepStatus'))$('#sleepStatus').textContent=timerDescription()}
setInterval(()=>{if(sleepDeadline&&Date.now()>=sleepDeadline)stopForSleep();else if(sleepDeadline)updateSleepBadge()},1000);
const endedBeforeSleep=audio.onended;audio.onended=function(){if(sleepAtTrackEnd){if(waveActive&&queue===waveQueue)waveFeedback('finished');stopForSleep();return}return endedBeforeSleep?.call(audio)};
const rowBeforeActions=row;row=function(t,i){const html=rowBeforeActions(t,i),at=html.lastIndexOf('</div>');return html.slice(0,at)+`<button class="track-more" data-track-actions="${esc(t.id)}" aria-label="Действия с треком ${esc(t.title)}" title="Действия с треком">•••</button>`+html.slice(at)};
const actionMenu=document.createElement('div');actionMenu.className='track-action-menu hidden';actionMenu.setAttribute('role','menu');document.body.append(actionMenu);let actionTrack=null,menuAnchor=null;
function closeTrackActions(){actionMenu.classList.add('hidden');actionTrack=null}
function showTrackActions(t,anchor){closeTrackActions();if(!t)return;actionTrack=t;menuAnchor=anchor;actionMenu.innerHTML=`<strong>${esc(t.title)}</strong><button role="menuitem" data-track-command="next" ${t.playable===false?'disabled':''}>Играть следующим</button><button role="menuitem" data-track-command="append" ${t.playable===false?'disabled':''}>В конец очереди</button><button role="menuitem" data-track-command="alternative">Найти в Яндексе / SoundCloud</button><button role="menuitem" data-add-to-playlist="${esc(t.id)}">Добавить в плейлист</button><button role="menuitem" data-track-command="copy">Копировать название</button>`;actionMenu.classList.remove('hidden');const r=anchor.getBoundingClientRect(),height=actionMenu.offsetHeight;actionMenu.style.left=Math.max(8,Math.min(r.right-260,innerWidth-275))+'px';actionMenu.style.top=Math.max(8,Math.min(r.bottom+7,innerHeight-height-12))+'px';actionMenu.querySelector('button:not([disabled])')?.focus()}
function queueTrack(t,next=false){if(t.id===current?.id){toast('Этот трек уже звучит.');return}const existing=queue.findIndex(x=>x.id===t.id);if(existing>=0)queue.splice(existing,1);const index=queue.findIndex(x=>x.id===current?.id);queue.splice(next?Math.max(0,index+1):queue.length,0,t);renderQueue();toast(next?'Трек будет следующим.':'Трек добавлен в очередь.')}
renderQueue=function(){$('#queueList').innerHTML=queue.length?queue.map((t,i)=>`<div class="queue-entry ${current?.id===t.id?'queue-current':''}"><button data-queue-play="${i}" class="queue-song"><img src="${esc(t.cover||image(0))}" alt=""><span><strong>${esc(t.title)}</strong><small>${esc(artist(t))}</small></span></button><div class="queue-tools"><button data-queue-up="${i}" ${i===0?'disabled':''} aria-label="Поднять ${esc(t.title)}">↑</button><button data-queue-remove="${i}" ${t.id===current?.id?'disabled':''} aria-label="Убрать ${esc(t.title)}">×</button></div></div>`).join(''):'<div class="empty"><p>Очередь пуста. Добавь трек через меню рядом с названием.</p></div>'};
async function findAlternative(t){if(!backend){toast('Поиск версий доступен в локальном приложении.');return}if(focusOpen)closeFocus();sourceFilter='all';go('search');const query=artist(t)+' '+t.title;$('#query').value=query;await search(query,'yandex,soundcloud')}
document.addEventListener('click',async e=>{const b=e.target.closest('button');if(!b)return;if(b.id==='commandsButton')openQuick();if(b.id==='sleepTimerButton')openQuick('timer');if(b.hasAttribute('data-close-quick'))closeQuick();if(b.dataset.command){const id=b.dataset.command;closeQuick();if(id==='timer'){openQuick('timer');return}if(id==='equalizer'){openEqualizer();return}if(id==='now')openFocus();else if(id==='queue'){$('#queue').classList.toggle('hidden');renderQueue()}else{if(focusOpen)closeFocus();go(id)}}if(b.dataset.sleepMinutes!==undefined){setSleep(+b.dataset.sleepMinutes);closeQuick()}if(b.hasAttribute('data-sleep-end')){setSleep(0,true);closeQuick()}if(b.dataset.trackActions){showTrackActions(find(b.dataset.trackActions),b);return}if(b.dataset.trackCommand&&actionTrack){const t=actionTrack,cmd=b.dataset.trackCommand;closeTrackActions();if(cmd==='next'||cmd==='append')queueTrack(t,cmd==='next');if(cmd==='alternative')findAlternative(t);if(cmd==='copy')try{await navigator.clipboard.writeText(artist(t)+' — '+t.title);toast('Название скопировано.')}catch{toast('Не удалось скопировать название.')}}if(b.dataset.queuePlay!==undefined)play(queue[+b.dataset.queuePlay]);if(b.dataset.queueUp!==undefined){const i=+b.dataset.queueUp;if(i>0)[queue[i-1],queue[i]]=[queue[i],queue[i-1]];renderQueue()}if(b.dataset.queueRemove!==undefined){const i=+b.dataset.queueRemove;if(queue[i]?.id!==current?.id)queue.splice(i,1);renderQueue()}});
document.addEventListener('click',e=>{if(!e.target.closest('.track-action-menu,[data-track-actions]'))closeTrackActions()});window.addEventListener('resize',closeTrackActions);
document.addEventListener('keydown',e=>{const editable=/INPUT|TEXTAREA|SELECT/.test(e.target.tagName)||e.target.isContentEditable;if((e.ctrlKey||e.metaKey)&&(e.code==='KeyK'||e.key.toLowerCase()==='k')){e.preventDefault();e.stopImmediatePropagation();quickDialog.open?closeQuick():openQuick();return}if(e.key==='Escape'&&!actionMenu.classList.contains('hidden')){e.preventDefault();closeTrackActions();menuAnchor?.focus();return}if(quickDialog.open){if(e.key==='Escape'){e.preventDefault();e.stopImmediatePropagation();closeQuick();return}if(e.key==='Enter'&&e.target.id==='commandSearch'){e.preventDefault();quickDialog.querySelector('[data-command]')?.click()}return}if(editable)return;if((e.ctrlKey||e.metaKey)&&(e.code==='KeyL'||e.key.toLowerCase()==='l')){e.preventDefault();e.stopImmediatePropagation();focusOpen?closeFocus():openFocus();return}if(e.key==='?'&&!e.ctrlKey&&!e.metaKey){e.preventDefault();openQuick();return}if(['ArrowLeft','ArrowRight'].includes(e.key)&&!e.target.closest('button,a,summary')){if(Number.isFinite(audio.duration)){e.preventDefault();audio.currentTime=Math.min(audio.duration,Math.max(0,audio.currentTime+(e.key==='ArrowRight'?1:-1)*(e.shiftKey?30:5)))}}},true);


